window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-653c1affef33740e"]={"versions": [{"id": "FIG-653c1affef33740e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung des Flash EEPROM Emulation Moduls (<code>Fee</code>) im Kontext der AUTOSAR Classic Platform (Memory Hardware Abstraction Layer). Dargestellt wird die Interaktion des Steuergerätemanagers (<code>EcuM</code>) und des Schedule Managers (<code>SchM</code>) mit dem Modul <code>Fee</code> während der synchronen und asynchronen Initialisierungsphasen unter Verwendung kombinierter Fragmente (<code>alt</code> und <code>loop</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (Lebenslinien, jeweils mit Stereotyp «module»):</p>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> (ECU State Manager): Aufrufer der Initialisierung.</li>\n<li><code>SchM</code> (Schedule Manager / BSW Scheduler): Trigger für zyklische Hauptfunktionen.</li>\n<li><code>Fee</code> (Flash EEPROM Emulation): Zu initialisierendes BSW-Modul.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li><code>Fee_Init()</code>: Synchroner Aufruf von <code>EcuM</code> an <code>Fee</code> ohne Übergabeparameter mit zugehörigem Return-Pfeil <code>Fee_Init()</code>.</li>\n<li><code>Fee_MainFunction()</code>: Zyklischer Aufruf von <code>SchM</code> an <code>Fee</code> mit zugehörigem Return-Pfeil <code>Fee_MainFunction()</code>.</li>\n</ul>\n<p class=\"fig-p\">Zustände (laut Notizen):</p>\n<ul class=\"fig-list\">\n<li><code>MEMIF_IDLE</code>: Modulstatus nach abgeschlossener Initialisierung.</li>\n<li><code>MEMIF_BUSY_INTERNAL</code>: Modulstatus während laufender interner Initialisierungsaktivitäten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich über ein <code>alt</code>-Fragment in zwei Ausführungspfade:</p>\n<ol class=\"fig-list\">\n<li><code>[synchronous initialization]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> ruft synchron <code>Fee_Init()</code> auf.</li>\n<li>Die Initialisierung wird vollständig innerhalb des Aufrufs abgeschlossen.</li>\n<li>Der Modulstatus wird auf <code>MEMIF_IDLE</code> gesetzt.</li>\n<li><code>Fee_Init()</code> kehrt synchron zu <code>EcuM</code> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>[asynchronous initialization]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> ruft <code>Fee_Init()</code> auf.</li>\n<li>Die Initialisierung wird innerhalb von <code>Fee_Init()</code> lediglich angestoßen; der Modulstatus wechselt zu <code>MEMIF_BUSY_INTERNAL</code>.</li>\n<li><code>Fee_Init()</code> kehrt daraufhin unmittelbar zu <code>EcuM</code> zurück.</li>\n<li>In einer Schleife (<code>loop</code>) ruft <code>SchM</code> wiederholt <code>Fee_MainFunction()</code> auf; der Modulstatus verbleibt dabei auf <code>MEMIF_BUSY_INTERNAL</code>.</li>\n<li>Beim finalen Aufruf von <code>Fee_MainFunction()</code> wird die Initialisierung beendet und der Modulstatus auf <code>MEMIF_IDLE</code> gesetzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert verbindlich das Zustands- und Aufrufverhalten für BSW-Treiberentwickler und Systemintegratoren:</p>\n<ul class=\"fig-list\">\n<li>Der Aufrufer (<code>EcuM</code>) muss berücksichtigen, dass <code>Fee</code> je nach Konfiguration oder Implementierung synchron oder asynchron initialisiert.</li>\n<li>Bei asynchroner Initialisierung ist die zyklische Ausführung von <code>Fee_MainFunction()</code> durch den BSW-Scheduler (<code>SchM</code>) zwingend erforderlich, um den Übergang von <code>MEMIF_BUSY_INTERNAL</code> zu <code>MEMIF_IDLE</code> herbeizuführen.</li>\n<li>Vor dem Erreichen von <code>MEMIF_IDLE</code> dürfen keine regulären Lese-, Schreib- oder Löschaufträge verarbeitet werden.</li>\n</ul>"}, {"id": "FIG-bff3f6b14ebe3c8c", "releases": ["R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung des Flash EEPROM Emulation Moduls (<code>Fee</code>) im Kontext der AUTOSAR Classic Platform (Memory Hardware Abstraction Layer). Dargestellt wird die Interaktion des Steuergerätemanagers (<code>EcuM</code>) und des Schedule Managers (<code>SchM</code>) mit dem Modul <code>Fee</code> während der synchronen und asynchronen Initialisierungsphasen unter Verwendung kombinierter Fragmente (<code>alt</code> und <code>loop</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (Lebenslinien, jeweils mit Stereotyp «module»):</p>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> (ECU State Manager): Aufrufer der Initialisierung.</li>\n<li><code>SchM</code> (Schedule Manager / BSW Scheduler): Trigger für zyklische Hauptfunktionen.</li>\n<li><code>Fee</code> (Flash EEPROM Emulation): Zu initialisierendes BSW-Modul.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li><code>Fee_Init()</code>: Synchroner Aufruf von <code>EcuM</code> an <code>Fee</code> ohne Übergabeparameter mit zugehörigem Return-Pfeil <code>Fee_Init()</code>.</li>\n<li><code>Fee_MainFunction()</code>: Zyklischer Aufruf von <code>SchM</code> an <code>Fee</code> mit zugehörigem Return-Pfeil <code>Fee_MainFunction()</code>.</li>\n</ul>\n<p class=\"fig-p\">Zustände (laut Notizen):</p>\n<ul class=\"fig-list\">\n<li><code>MEMIF_IDLE</code>: Modulstatus nach abgeschlossener Initialisierung.</li>\n<li><code>MEMIF_BUSY_INTERNAL</code>: Modulstatus während laufender interner Initialisierungsaktivitäten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich über ein <code>alt</code>-Fragment in zwei Ausführungspfade:</p>\n<ol class=\"fig-list\">\n<li><code>[synchronous initialization]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> ruft synchron <code>Fee_Init()</code> auf.</li>\n<li>Die Initialisierung wird vollständig innerhalb des Aufrufs abgeschlossen.</li>\n<li>Der Modulstatus wird auf <code>MEMIF_IDLE</code> gesetzt.</li>\n<li><code>Fee_Init()</code> kehrt synchron zu <code>EcuM</code> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>[asynchronous initialization]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> ruft <code>Fee_Init()</code> auf.</li>\n<li>Die Initialisierung wird innerhalb von <code>Fee_Init()</code> lediglich angestoßen; der Modulstatus wechselt zu <code>MEMIF_BUSY_INTERNAL</code>.</li>\n<li><code>Fee_Init()</code> kehrt daraufhin unmittelbar zu <code>EcuM</code> zurück.</li>\n<li>In einer Schleife (<code>loop</code>) ruft <code>SchM</code> wiederholt <code>Fee_MainFunction()</code> auf; der Modulstatus verbleibt dabei auf <code>MEMIF_BUSY_INTERNAL</code>.</li>\n<li>Beim finalen Aufruf von <code>Fee_MainFunction()</code> wird die Initialisierung beendet und der Modulstatus auf <code>MEMIF_IDLE</code> gesetzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert verbindlich das Zustands- und Aufrufverhalten für BSW-Treiberentwickler und Systemintegratoren:</p>\n<ul class=\"fig-list\">\n<li>Der Aufrufer (<code>EcuM</code>) muss berücksichtigen, dass <code>Fee</code> je nach Konfiguration oder Implementierung synchron oder asynchron initialisiert.</li>\n<li>Bei asynchroner Initialisierung ist die zyklische Ausführung von <code>Fee_MainFunction()</code> durch den BSW-Scheduler (<code>SchM</code>) zwingend erforderlich, um den Übergang von <code>MEMIF_BUSY_INTERNAL</code> zu <code>MEMIF_IDLE</code> herbeizuführen.</li>\n<li>Vor dem Erreichen von <code>MEMIF_IDLE</code> dürfen keine regulären Lese-, Schreib- oder Löschaufträge verarbeitet werden.</li>\n</ul>"}, {"id": "FIG-639ddb09bc9831c5", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung des Flash EEPROM Emulation Moduls (<code>Fee</code>) im Kontext der AUTOSAR Classic Platform (Memory Hardware Abstraction Layer). Dargestellt wird die Interaktion des Steuergerätemanagers (<code>EcuM</code>) und des Schedule Managers (<code>SchM</code>) mit dem Modul <code>Fee</code> während der synchronen und asynchronen Initialisierungsphasen unter Verwendung kombinierter Fragmente (<code>alt</code> und <code>loop</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (Lebenslinien, jeweils mit Stereotyp «module»):</p>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> (ECU State Manager): Aufrufer der Initialisierung.</li>\n<li><code>SchM</code> (Schedule Manager / BSW Scheduler): Trigger für zyklische Hauptfunktionen.</li>\n<li><code>Fee</code> (Flash EEPROM Emulation): Zu initialisierendes BSW-Modul.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li><code>Fee_Init()</code>: Synchroner Aufruf von <code>EcuM</code> an <code>Fee</code> ohne Übergabeparameter mit zugehörigem Return-Pfeil <code>Fee_Init()</code>.</li>\n<li><code>Fee_MainFunction()</code>: Zyklischer Aufruf von <code>SchM</code> an <code>Fee</code> mit zugehörigem Return-Pfeil <code>Fee_MainFunction()</code>.</li>\n</ul>\n<p class=\"fig-p\">Zustände (laut Notizen):</p>\n<ul class=\"fig-list\">\n<li><code>MEMIF_IDLE</code>: Modulstatus nach abgeschlossener Initialisierung.</li>\n<li><code>MEMIF_BUSY_INTERNAL</code>: Modulstatus während laufender interner Initialisierungsaktivitäten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich über ein <code>alt</code>-Fragment in zwei Ausführungspfade:</p>\n<ol class=\"fig-list\">\n<li><code>[synchronous initialization]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> ruft synchron <code>Fee_Init()</code> auf.</li>\n<li>Die Initialisierung wird vollständig innerhalb des Aufrufs abgeschlossen.</li>\n<li>Der Modulstatus wird auf <code>MEMIF_IDLE</code> gesetzt.</li>\n<li><code>Fee_Init()</code> kehrt synchron zu <code>EcuM</code> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>[asynchronous initialization]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> ruft <code>Fee_Init()</code> auf.</li>\n<li>Die Initialisierung wird innerhalb von <code>Fee_Init()</code> lediglich angestoßen; der Modulstatus wechselt zu <code>MEMIF_BUSY_INTERNAL</code>.</li>\n<li><code>Fee_Init()</code> kehrt daraufhin unmittelbar zu <code>EcuM</code> zurück.</li>\n<li>In einer Schleife (<code>loop</code>) ruft <code>SchM</code> wiederholt <code>Fee_MainFunction()</code> auf; der Modulstatus verbleibt dabei auf <code>MEMIF_BUSY_INTERNAL</code>.</li>\n<li>Beim finalen Aufruf von <code>Fee_MainFunction()</code> wird die Initialisierung beendet und der Modulstatus auf <code>MEMIF_IDLE</code> gesetzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert verbindlich das Zustands- und Aufrufverhalten für BSW-Treiberentwickler und Systemintegratoren:</p>\n<ul class=\"fig-list\">\n<li>Der Aufrufer (<code>EcuM</code>) muss berücksichtigen, dass <code>Fee</code> je nach Konfiguration oder Implementierung synchron oder asynchron initialisiert.</li>\n<li>Bei asynchroner Initialisierung ist die zyklische Ausführung von <code>Fee_MainFunction()</code> durch den BSW-Scheduler (<code>SchM</code>) zwingend erforderlich, um den Übergang von <code>MEMIF_BUSY_INTERNAL</code> zu <code>MEMIF_IDLE</code> herbeizuführen.</li>\n<li>Vor dem Erreichen von <code>MEMIF_IDLE</code> dürfen keine regulären Lese-, Schreib- oder Löschaufträge verarbeitet werden.</li>\n</ul>"}, {"id": "FIG-86877f41d7bd1bc2", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung des Flash EEPROM Emulation Moduls (<code>Fee</code>) im Kontext der AUTOSAR Classic Platform (Memory Hardware Abstraction Layer). Dargestellt wird die Interaktion des Steuergerätemanagers (<code>EcuM</code>) und des Schedule Managers (<code>SchM</code>) mit dem Modul <code>Fee</code> während der synchronen und asynchronen Initialisierungsphasen unter Verwendung kombinierter Fragmente (<code>alt</code> und <code>loop</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (Lebenslinien, jeweils mit Stereotyp «module»):</p>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> (ECU State Manager): Aufrufer der Initialisierung.</li>\n<li><code>SchM</code> (Schedule Manager / BSW Scheduler): Trigger für zyklische Hauptfunktionen.</li>\n<li><code>Fee</code> (Flash EEPROM Emulation): Zu initialisierendes BSW-Modul.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li><code>Fee_Init(const Fee_ConfigType*)</code>: Aufruf von <code>EcuM</code> an <code>Fee</code> mit Konfigurationszeiger; Rückkehrpfeil beschriftet mit <code>Fee_Init()</code>.</li>\n<li><code>Fee_MainFunction()</code>: Zyklischer Aufruf von <code>SchM</code> an <code>Fee</code> mit zugehörigem Return-Pfeil <code>Fee_MainFunction()</code>.</li>\n</ul>\n<p class=\"fig-p\">Zustände (laut Notizen):</p>\n<ul class=\"fig-list\">\n<li><code>MEMIF_IDLE</code>: Modulstatus nach abgeschlossener Initialisierung.</li>\n<li><code>MEMIF_BUSY_INTERNAL</code>: Modulstatus während laufender interner Initialisierungsaktivitäten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich über ein <code>alt</code>-Fragment in zwei Ausführungspfade:</p>\n<ol class=\"fig-list\">\n<li><code>[synchronous initialization]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> ruft synchron <code>Fee_Init(const Fee_ConfigType*)</code> auf.</li>\n<li>Die Initialisierung wird vollständig innerhalb des Aufrufs abgeschlossen.</li>\n<li>Der Modulstatus wird auf <code>MEMIF_IDLE</code> gesetzt.</li>\n<li>Der Aufruf kehrt synchron als <code>Fee_Init()</code> zu <code>EcuM</code> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>[asynchronous initialization]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> ruft <code>Fee_Init(const Fee_ConfigType*)</code> auf.</li>\n<li>Die Initialisierung wird innerhalb von <code>Fee_Init</code> lediglich angestoßen; der Modulstatus wechselt zu <code>MEMIF_BUSY_INTERNAL</code>.</li>\n<li>Der Aufruf kehrt als <code>Fee_Init()</code> zu <code>EcuM</code> zurück.</li>\n<li>In einer Schleife (<code>loop</code>) ruft <code>SchM</code> wiederholt <code>Fee_MainFunction()</code> auf; der Modulstatus verbleibt dabei auf <code>MEMIF_BUSY_INTERNAL</code>.</li>\n<li>Beim finalen Aufruf von <code>Fee_MainFunction()</code> wird die Initialisierung beendet und der Modulstatus auf <code>MEMIF_IDLE</code> gesetzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert verbindlich das Zustands- und Aufrufverhalten für BSW-Treiberentwickler und Systemintegratoren:</p>\n<ul class=\"fig-list\">\n<li>Der Aufrufer (<code>EcuM</code>) übergibt bei der Initialisierung einen typisierten Zeiger auf die Konfigurationsstruktur (<code>const Fee_ConfigType*</code>).</li>\n<li><code>EcuM</code> muss berücksichtigen, dass <code>Fee</code> je nach Konfiguration synchron oder asynchron initialisiert.</li>\n<li>Bei asynchroner Initialisierung ist die zyklische Ausführung von <code>Fee_MainFunction()</code> durch den BSW-Scheduler (<code>SchM</code>) zwingend erforderlich, um den Übergang von <code>MEMIF_BUSY_INTERNAL</code> zu <code>MEMIF_IDLE</code> herbeizuführen.</li>\n<li>Vor dem Erreichen von <code>MEMIF_IDLE</code> dürfen keine regulären Aufträge verarbeitet werden.</li>\n</ul>"}], "trans": [{"from": "FIG-653c1affef33740e", "to": "FIG-bff3f6b14ebe3c8c", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bff3f6b14ebe3c8c", "to": "FIG-639ddb09bc9831c5", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-639ddb09bc9831c5", "to": "FIG-86877f41d7bd1bc2", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Operationsaufruf <code>Fee_Init()</code>: Aufruf durch <code>EcuM</code> wird um den Konfigurationszeiger-Parameter parametrisiert zu <code>Fee_Init(const Fee_ConfigType*)</code> (sowohl im synchronen als auch im asynchronen Ausführungszweig des <code>alt</code>-Fragments). Der Rückkehrpfeil bleibt mit <code>Fee_Init()</code> beschriftet.</li>\n</ul>"}]};
